CREATE OR REPLACE TABLE {{DATABASE}}.BRONZE.ORDER_UPDATES (ORDER_ID INTEGER,CUSTOMER_ID INTEGER,ORDER_DATE DATE,STATUS VARCHAR);
INSERT INTO {{DATABASE}}.BRONZE.ORDER_UPDATES VALUES (1000,80,'2024-02-11','SHIPPED'),(9999,1,CURRENT_DATE(),'NEW');
MERGE INTO {{DATABASE}}.SILVER.ORDERS TARGET USING {{DATABASE}}.BRONZE.ORDER_UPDATES SOURCE ON TARGET.ORDER_ID=SOURCE.ORDER_ID WHEN MATCHED THEN UPDATE SET TARGET.CUSTOMER_ID=SOURCE.CUSTOMER_ID,TARGET.ORDER_DATE=SOURCE.ORDER_DATE,TARGET.STATUS=UPPER(TRIM(SOURCE.STATUS)) WHEN NOT MATCHED THEN INSERT (ORDER_ID,CUSTOMER_ID,ORDER_DATE,STATUS) VALUES (SOURCE.ORDER_ID,SOURCE.CUSTOMER_ID,SOURCE.ORDER_DATE,UPPER(TRIM(SOURCE.STATUS)));
